# Liebermann, Gesetze I p. 658: Lond 32 C–C 6 (insertion into ECf retr; cited as ECf 32 C …)
D = lambda de, en: (de, en)
LOND_ED = 'This passage is not part of ECf or ECf retr: it is one of the additions of the London collection (Leges Anglorum s. XIII in. Londoniis collectae), which Liebermann prints across the page as an insertion into ECf retr. 32 (32 A–E, pp. 655–660). The dictionary cites it as “ECf 32 C …”, so it is kept with ECf here.'
LD = D('<i>fehlt Ld</i>', 'lacking in Ld')
B = D('Bryt. <i>Ld</i>', 'Bryt. Ld')
FC = D('sicut homines proprii <i>werden Fremde begünstigt in Freibriefen, so seit</i> 1157 <i>Cölner; Höhlbaum</i> Hansisch. Urk. I <i>S.</i> 8. 16. 22', 'foreigners are favoured sicut homines proprii in charters, so from 1157 the men of Cologne; Höhlbaum, Hansisch. Urk. I pp. 8. 16. 22')
FF = D('<i>s. o.</i> 32 A 5', 'see above, 32 A 5')
FO = D('<i>seit</i> 1100 <i>heirathete das Englische Königshaus in die Dynastien von Schottland, Deutschland, Wales, Bretagne, Sachsen im Dienste Grossbritannischer und Europäischer Politik: was vielleicht der Londoner Phantasie Anregung gab. Englischer Adel heirathete manchmal in Wales und Schottland. In der Hauptsache träumt der Londoner; statt</i> Angli <i>setzt er</i> Norwegienses 32 E 2',
       'from 1100 the English royal house married into the dynasties of Scotland, Germany, Wales, Brittany and Saxony in the service of British and European policy: which perhaps stimulated the Londoner’s imagination. The English nobility sometimes married into Wales and Scotland. In the main the Londoner is dreaming; instead of Angli he puts Norwegienses at 32 E 2')
def L(n, text, notes, margin=None, extra=None):
    c = {'code': 'ECf', 'n': n, 'page': 658, 'keys': ['ECf ' + n], 'text': text, 'notes': notes, 'editorial': [LOND_ED] + (extra or [])}
    if margin: c['margin'] = margin
    return c
CLAUSES = [
 L('32 C', '<sp>De{f:a} illis, qui possunt et debent de iure cohabitare et remanere in regno Britannie{1}.</sp> Britones{f:b}{1} uero Armorice{2} cum ueniunt in regno isto, suscipi debent et in regno protegi sicut proprii{f:c} ciues: de corpore regni huius exierunt{f:d} quondam, de sanguine Britonum{1} regni huius.',
   {'f:a': D('<i>hier will sich Londoner Fremdenpolitik historisch begründen, mehrfach durch Blutsverwandtschaft, auf welche sich die Engländer damals oft bezogen, wenn Bund mit Deutschen Vortheil versprach; vgl. Math. Paris.</i> 1257, Mon. Germ. 28, 367', 'here London’s policy towards foreigners seeks a historical foundation, several times through kinship of blood, to which the English then often appealed when alliance with Germans promised advantage; cf. Math. Paris. 1257, Mon. Germ. 28, 367'),
    'f:b': D('<i>wohl geschrieben oder veranlasst, bevor</i> 1199 <i>die Personal-Union von England und Bretagne endete, oder als</i> 1207 <i>Herzog Wido Englands Freund war</i>', 'probably written or occasioned before the personal union of England and Brittany ended in 1199, or when Duke Guy was England’s friend in 1207'),
    'f:c': FC, 'f:d': D('<i>im</i> 5. 6. <i>Jh.; Loth</i> Emigr. Bret. <i>p.</i> 174. <i>Der Londoner benutzt wohl nur</i> Galfr. Monm. XII 15 <i>f.</i>', 'in the 5th and 6th centuries; Loth, Emigr. Bret. p. 174. The Londoner probably uses only Geoffrey of Monmouth XII 15 f.'),
    1: B, 2: D('-ci c. uenerint <i>Co Ld</i>', '-ci c. uenerint Co Ld')}),
 L('32 C 1', 'Guti{f:e} uero similiter cum ueniunt, suscipi debent et protegi in regno isto sicut coniurati{f:f} fratres nostri{3} et sicut propinqui et proprii{f:c} ciues regni huius: exierunt enim quondam de nobili sanguine Anglorum.',
   {'f:e': D('<i>wohl nicht Deutsche Kaufleute Gothlands, die England</i> 1237 <i>privilegirte, sondern</i> Jüten <i>als Vertreter der</i> Dänen, <i>die im</i> 12. <i>Jh. Londonern gleich standen; Höhlbaum</i> III <i>S.</i> 389; <i>Steenstrup</i> Danelag 380; <i>Johann privilegirt</i> 1208 <i>Schiffe aus</i> Denemargia et Norweia; Rot. lit. Patent. <i>p.</i> 83. <i>Auch Will. Malm.</i> Reg. II 116 <i>legt</i> Anglia vetus inter Saxones et Gothos. <i>Ähnliches sagt der Londoner von Norwegern</i> 32 E 3 <i>f.</i>',
             'probably not the German merchants of Gotland, whom England privileged in 1237, but Jutes as representatives of the Danes, who in the 12th century stood equal with Londoners; Höhlbaum III p. 389; Steenstrup, Danelag 380; John privileges ships from Denemargia et Norweia in 1208; Rot. lit. Patent. p. 83. Will. Malm., Reg. II 116, too places Anglia vetus inter Saxones et Gothos. The Londoner says something similar of the Norwegians, 32 E 3 f.'),
    'f:f': FF, 'f:c': FC, 3: D('unde <i>Co Or;</i> n. et <i>fehlt Ld</i>', 'unde Co Or; n. et lacking in Ld')}),
 L('32 C 1a', 'Saxones{4} uero{f:g} Germanie{5} cum ueniunt in regno, suscipi debent et protegi in regno isto sicut coniurati{f:f} fratres nostri et sicut proprii{f:c} ciues regni huius: exierunt enim quondam de sanguine Anglorum, scilicet de Engra{f:h} ciuitate, et Anglici de sanguine illorum, et semper efficiuntur populus unus et gens una{f:i}.',
   {'f:g': D('<i>Gefühl des Bundes der Welfen mit Heinrich II. und seinen Söhnen oder Abbild des wirklichen damaligen Vorrechtes Norddeutscher Händler; vgl.</i> IV Atr. 2, 8; <i>Höhlbaum</i> III <i>S.</i> 281; <i>n.</i> 59. 63. 69. 110', 'a sense of the alliance of the Welfs with Henry II and his sons, or a reflection of the real privilege of North German traders at that time; cf. IV Atr. 2, 8; Höhlbaum III p. 281; n. 59. 63. 69. 110'),
    'f:f': FF, 'f:c': FC,
    'f:h': D('<i>der Londoner meint das Land</i> Angeln, <i>ihm</i> (<i>mittelbar</i>) <i>aus Bæda’s</i> Angulus <i>bekannt. Er verderbte den Namen vielleicht durch phonetische Orthographie des Anlauts, vielleicht aber zog er auch confus</i> Engern, <i>das Land an der Weser heran, worüber Norddeutsche erzählen mochten</i>', 'the Londoner means the land of Angeln, known to him (indirectly) from Bede’s Angulus. He perhaps corrupted the name through a phonetic spelling of the initial, but perhaps he also confusedly drew in Engern, the land on the Weser, of which North Germans may have told'),
    'f:i': D('Connubium <i>als Mittel zur Einung der Nation auch</i> 32 C 4 <i>ff.</i> E 2. <i>Ludwig IX.</i> precepit ut federe maritali Franci Normannis concatenarentur; <i>Math. Paris. ebd.</i> 370', 'connubium as a means of uniting the nation also at 32 C 4 ff. and E 2. Louis IX precepit ut federe maritali Franci Normannis concatenarentur; Math. Paris., ibid. 370'),
    4: D('Saxones—Anglorum <i>fehlt Ld</i>', 'Saxones—Anglorum lacking in Ld'), 5: D('-mannie <i>K</i>', '-mannie K')}),
 L('32 C 2', 'Ita{f:k} constituit optimus Yne{6} rex Anglorum, qui electus{f:l} fuit in regem per Angliam{7} et qui primo optinuit monarchiam tocius{f:m} regni huius post aduentum Anglorum in Britanniam{1}. Fuit{8} enim primus rex coronatus Anglorum et Britonum{1} simul manentium{9} in Britannia post aduentum Saxonum Germanie in{10} Britannia, scilicet post acceptam fidem a beato Gregorio per sanctum Augustinum.',
   {'f:k': D('<i>der Londoner schiebt Ine auch sonst Recht und Politik vom Ende des</i> 12. <i>Jhs. unter; zwar steht dieser Abschnitt in den</i> Concilia M. Brit. <i>Spelman’s</i> 219 <i>und Wilkins’</i> I 74, <i>gilt aber als Fabel schon Spelman, Henschen</i> Acta sanct., Febr. 6, <i>und Mabillon</i> Acta sanct. Bened. III 494', 'the Londoner elsewhere too foists law and policy of the late 12th century on Ine; this section does stand in Spelman’s Concilia M. Brit. 219 and Wilkins’ I 74, but already Spelman, Henschen (Acta sanct., Feb. 6) and Mabillon (Acta sanct. Bened. III 494) regard it as a fable'),
    'f:l': D('<i>der Monarch soll Wahlkönig scheinen</i>', 'the monarch is to appear an elected king'),
    'f:m': D('<i>so lügt der Londoner schon vorher: meine</i> Leg. Angl. <i>S.</i> 14. <i>Auch Ralf Niger macht Ine von Wessex</i> (<i>s. o. S.</i> 88) <i>zum ersten König ganz Englands</i>', 'the Londoner lies thus already earlier: my Leg. Angl. p. 14. Ralph Niger too makes Ine of Wessex (see above, p. 88) the first king of all England'),
    6: D('Ina <i>Ld</i>', 'Ina Ld'), 7: D('angl’m <i>K;</i> angelum <i>Or Ld</i>', 'angl’m K; angelum Or Ld'), 1: B, 8: D('Pr. e. fu. <i>Co Or Ld</i>', 'Pr. e. fu. Co Or Ld'), 9: D('<i>fehlt K</i>', 'lacking in K'), 10: D('in B. <i>fehlt Ld</i>', 'in B. lacking in Ld')},
   ['a. 449 (aduentum)', 'a. 596 (acceptam)'], ['Liebermann marks “aduentum” and “acceptam” with daggers for his marginal dates, 449 and 596.']),
 L('32 C 3', 'Cepit enim predictus Ina uxorem{11} suam demum Walam{f:n} nomine, propter quam uocata est Wallia illa{12} terra que quondam uocabatur Cambria{13}. Bigamus enim fuit. Cepit enim{14} cum ista{15} ultima sua{16} uxore Cambriam{13} et Cornubiam et coronam benedictam Britannie, que fuit{17} ultimo Cadualladrio{18} regi Britannie.',
   {'f:n': D('Iam non uocabantur Britones, sed Gualenses, uocabulum .. a Guales regina; <i>Galfr. Monm.</i> XII 19 (<i>was Girald</i> Descr. Cambr. 7 <i>ablehnt</i>); <i>dort</i> (<i>c.</i> 18) <i>lässt Cadwalladrus, der letzte Britenkönig,</i> Iny nepotem <i>die Briten regiren. Da in der Quelle Ine’s Frau anders hiess, muss der Londoner</i> Wala <i>zur zweiten Gemahlin Ine’s machen</i>',
             'Iam non uocabantur Britones, sed Gualenses, uocabulum .. a Guales regina; Geoffrey of Monmouth XII 19 (which Gerald, Descr. Cambr. 7, rejects); there (c. 18) Cadwalader, the last king of the Britons, lets Iny nepotem rule the Britons. Since in the source Ine’s wife had another name, the Londoner has to make Wala Ine’s second wife'),
    11: D('in u. s. Gua. <i>Ld</i>', 'in u. s. Gua. Ld'), 12: D('i. t. <i>fehlt K</i>', 'i. t. lacking in K'), 13: D('Ka. <i>Co Or</i>', 'Ka. Co Or'), 14: D('autem <i>Ld</i>', 'autem Ld'), 15: D('<i>fehlt Co Or Ld</i>', 'lacking in Co Or Ld'),
    16: D('u. s. <i>Ld</i>', 'u. s. Ld'), 17: D('fuerat <i>Ld</i>', 'fuerat Ld'), 18: D('Cadwaladro <i>Ld</i>', 'Cadwaladro Ld')}),
 L('32 C 4', 'Et uniuersi Angli, qui tunc temporis in{10} Britannia{19} extiterunt, uxores{f:o} suas ceperunt de Britonum{1} genere, et Britones{1} uxores suas de illustri{20} sanguine et genere Anglorum, scilicet{21} de genere Saxonum. Hoc enim factum fuit per commune consilium et assensum omnium episcoporum et principum, procerum, comitum et omnium sapientum seniorum et populorum tocius regni et per preceptum regis Ine predicti.',
   {'f:o': FO, 10: D('in B. <i>fehlt Ld</i>', 'in B. lacking in Ld'), 19: D('-iam <i>K Co</i>', '-iam K Co'), 1: B, 20: D('-stro <i>Co</i>', '-stro Co'), 21: D('hoc est <i>Co Or Ld</i>', 'hoc est Co Or Ld')}),
 L('32 C 5', 'Multi uero Angli{f:o} ceperunt uxores suas de sanguine et genere Anglorum{22} Germanie{23}, et quidam Angli ceperunt uxores suas de sanguine et genere Scotorum{24}; proceres uero Scotorum, et Scotti{25} fere omnes, ceperunt uxores suas de optimo sanguine{26} et genere Anglorum Germanie; et ita fuerunt tunc temporis per uniuersum regnum Britannie{1} duo in carne una.',
   {'f:o': FO, 22: D('Angl.—sang. et <i>fehlt Or</i>', 'Angl.—sang. et lacking in Or'), 23: D('-mannie <i>K stets</i>', '-mannie K always'), 24: D('Scott. <i>Co stets</i>', 'Scott. Co always'), 25: D('Scoti <i>Ld</i>', 'Scoti Ld'),
    26: D('g. et s. <i>Ld</i>', 'g. et s. Ld'), 1: B}, ['Gen. 2, 24'], ['Liebermann marks “duo” with a dagger for his marginal reference to Genesis 2, 24.']),
 L('32 C 6', 'Et taliter constituit rectum coniugium{f:p} — et deleuit fornicationem et immunditiam a regno — et recta iudicia{27} pro stabilitate regni et confirmatione populorum suorum{28} benigna sedulitate.',
   {'f:p': D('coniugium <i>war nur ein Schnitzer des Quadr. statt</i> Gesetz, <i>o. S.</i> 89', 'coniugium was only a blunder of Quadr. for law (æ), above p. 89'),
    27: D('iustitia <i>Ld</i>', 'iustitia Ld'), 28: LD}, ['Quadr. Ine Prol.'],
   ['Liebermann prints the words taken from Quadripartitus’ Ine Prologue (constituit rectum coniugium; et recta iudicia … sedulitate) in smaller type.']),
]
